import json
import csv

def get_cvss_score(cvss_obj):
    if not cvss_obj:
        return "N/A"

    # Priority order: nvd, ghsa, redhat
    sources = ['nvd', 'ghsa', 'redhat']
    for source in sources:
        if source in cvss_obj and 'V3Score' in cvss_obj[source]:
            return str(cvss_obj[source]['V3Score'])

    # If no V3Score in priority sources, try to find any V3Score
    for source, data in cvss_obj.items():
        if 'V3Score' in data:
            return str(data['V3Score'])

    return "N/A"

def process_trivy_report(json_path, csv_path):
    try:
        with open(json_path, 'r') as f:
            data = json.load(f)
    except FileNotFoundError:
        print(f"Error: {json_path} not found.")
        return

    vulnerabilities = []

    if 'Results' in data:
        for result in data['Results']:
            if 'Vulnerabilities' in result:
                for vuln in result['Vulnerabilities']:
                    severity = vuln.get('Severity', 'UNKNOWN')

                    if severity in ['HIGH', 'CRITICAL']:
                        pkg_name = vuln.get('PkgName', 'N/A')
                        version = vuln.get('InstalledVersion', 'N/A')
                        cve_id = vuln.get('VulnerabilityID', 'N/A')
                        cvss_score = get_cvss_score(vuln.get('CVSS'))
                        fixed_version = vuln.get('FixedVersion', 'N/A')
                        title = vuln.get('Title', 'N/A')
                        url = vuln.get('PrimaryURL', 'N/A')

                        vulnerabilities.append([
                            pkg_name,
                            version,
                            cve_id,
                            severity,
                            cvss_score,
                            fixed_version,
                            title,
                            url
                        ])

    # Write to CSV
    header = ['Package', 'Version', 'CVE_ID', 'Severity', 'CVSS_Score', 'Fixed_Version', 'Title', 'Url']

    with open(csv_path, 'w', newline='') as f:
        writer = csv.writer(f)
        writer.writerow(header)
        writer.writerows(vulnerabilities)

    print(f"Successfully wrote {len(vulnerabilities)} vulnerabilities to {csv_path}")

if __name__ == "__main__":
    process_trivy_report('/root/trivy_report.json', '/root/security_audit.csv')

